contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving the minimal sequence
    // params: recipient to receive withdrawal and amount of ETH to seed contract balance
    function run(address payable recipient, uint seed) public {
        // precondition: this test sends seed wei into C so it can pay out
        require(address(this).balance >= seed);
        // fund contract C with seed
        (bool s1,) = address(c).call{value: seed}("");
        require(s1);

        // ensure recipient hasn't claimed bonus yet by calling the function that both sets reward and triggers withdrawal
        // This will: add 100 to rewardsForA[recipient], then call withdrawReward(recipient) which sends that amount
        c.getFirstWithdrawalBonus(recipient);

        // Observables:
        // 1) recipient's balance relative change: we can only observe address(this) and address(c).balance.
        // But the external recipient is arbitrary; instead we assert on contract C's balance decreased by exactly 100.
        // So compute remaining balance of c and assert it equals seed - 100.

        uint expected = seed - 100;
        uint actual = address(c).balance;

        // The key distinguishing rule: after getFirstWithdrawalBonus, the contract's balance must have decreased by exactly 100 (no leftover 1 sentinel)
        assert(actual == expected);
    }

    // allow contract to receive ETH for seeding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public payable {
        require(true);
        bool reverted;
        // state-changing call on c must be a top-level statement
        try c.withdrawReward(recipient) { reverted = false; } catch { reverted = true; }
        // In the original contract, withdrawReward never reverts for any recipient.
        assert(!reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // take recipient and an initial fund amount to seed rewards externally if needed
    function run(address recipient) public payable {
        // We require nothing about msg.value; just require recipient is nonzero to avoid trivial invalid address
        require(recipient != address(0));
        // Call withdrawReward and record whether it reverted
        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: withdrawReward should not revert for any recipient (i.e., reverted == false)
        assert(!reverted);
    }
    receive() external payable {}
}

