contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint seedFund) public payable {
        require(address(this).balance >= seedFund);
        // fund C so it can pay out rewards
        (bool s, ) = address(c).call{value: seedFund}(abi.encodeWithSignature(""));
        // call withdrawReward and observe whether it reverts
        bool reverted;
        try c.withdrawReward(recipient) { reverted = false; } catch { reverted = true; }
        // The rule: if C has sufficient ETH (its balance >= amount it will attempt to send), withdrawReward should not revert.
        // We cannot read rewardsForA directly, so express the rule using the fact that when C has at least 1 wei it should not revert for any recipient
        // (this captures the mutant which leaves a nonzero sentinel causing a revert when balance insufficient).
        assert(!(address(c).balance >= 1 && reverted));
    }
    receive() external payable { }
