import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed recipient address; we must ensure it is a contract that will accept Ether so the low-level call in withdrawReward succeeds
    function testFuzz_property(address recipient) public {
        // avoid zero address and keep domain wide
        vm.assume(recipient != address(0));

        // deploy a simple receiver at the provided address by creating a new Receiver and ignoring recipient param —
        // we cannot deploy at an arbitrary address deterministically, so instead we deploy a Receiver and use its address as the recipient
        Receiver r = new Receiver();
        address payable recv = payable(address(r));

        // ensure receiver has enough balance to not affect sending, and fund the test caller to send Ether if needed
        vm.deal(address(this), 1 ether);

        // Drive the contract: call getFirstWithdrawalBonus with the receiver address
        // this should add 100 to rewardsForA[recv], then call withdrawReward which sends that amount and zeros the storage in the correct contract
        c.getFirstWithdrawalBonus(recv);

        // The general property (observed via public getter rewardsForA) is that rewardsForA[recv] == 0 for the correct contract
        // (the mutant sets it to 1 and will thus break this assertion for some inputs)
        // exactly one assertion as required:
        assertTrue(c.rewardsForA(recv) == 0);
    }
}

