contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter: an address that will act as the recipient (must be a contract to accept payments)
    function testFuzz_property(address recipientAddr) public {
        // bound the address to avoid the zero address which could be problematic
        vm.assume(recipientAddr != address(0));

        // deploy a helper at a deterministic address derived from the fuzzed input by using create2-like variability
        // but simplest: deploy a new accepting recipient contract and ignore recipientAddr other than for entropy
        AcceptingRecipient r = new AcceptingRecipient();

        // ensure the contract has enough funds to pay the bonus
        vm.deal(address(c), 0); // start from zero
        // give c enough ether by sending from this test contract
        payable(address(c)).transfer(0);

        // The getFirstWithdrawalBonus will credit rewardsForA[recipient] += 100 and then call withdrawReward(recipient)
        // which attempts to send amountToWithdraw to the recipient. The helper AcceptingRecipient accepts ETH.

        // call getFirstWithdrawalBonus on c with the helper's address
        // no Ether needs to be sent with the call because c pays from its own state (we simulate by pre-funding c)
        // Fund c with 100 wei so it can successfully send
        vm.deal(address(this), 100);
        vm.prank(address(this));
        (bool sentToC, ) = address(c).call{value: 100}("");
        require(sentToC, "fund c failed");

        // Now invoke the function under test for the helper's address
        c.getFirstWithdrawalBonus(address(r));

        // Exactly one assertion: after the call, the reference contract ensures rewardsForA[recipient] == 0 for every recipient.
        // Observe via the public getter generated for rewardsForA (it exists in the reference C as public).
        // The mutant that sets rewardsForA[recipient] = 1 before the external call can leave it equal to 1, breaking this rule.
        assertTrue(c.rewardsForA(address(r)) == 0);
    }
}

