contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an address recipient that will be a contract which accepts funds, and a random uint to vary EOA funding
    function testFuzz_property(address recipientProxy, uint256 seed) public {
        // keep recipientProxy non-zero and not the test contract or c
        vm.assume(recipientProxy != address(0));
        vm.assume(recipientProxy != address(this));
        vm.assume(recipientProxy != address(c));

        // Deploy a minimal accepting helper at an address unrelated to the fuzzed address: we ignore recipientProxy's code
        // but use it as a source of entropy to choose which helper to target. We deploy an accepting contract that simply
        // receives and does nothing (call succeeds). That models the common successful external call case the mutant
        // will leave state different for.
        AcceptingReceiver recv = new AcceptingReceiver();

        address recipient = address(recv);

        // ensure c has enough balance to pay the bonus (getFirstWithdrawalBonus adds 100 and then withdraws)
        vm.deal(address(c), 100 ether);

        // Call getFirstWithdrawalBonus with the accepting recipient. No reverts expected in reference.
        // We call without specifying value since the contract pays from its own balance.
        bool ok;
        try c.getFirstWithdrawalBonus(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general invariant: after a successful getFirstWithdrawalBonus(recipient) on the reference
        // implementation, the recorded rewardsForA[recipient] must be 0. The mutant that sets the mapping to 1
        // before the external call can leave it as 1 when the external call succeeds, violating this.
        // We assert that the getter reports 0 for the recipient. This holds for the reference for all inputs,
        // but the mutant will fail for some inputs (when the external call succeeds) causing this assert to fail.
        assertTrue(c.rewardsForA(recipient) == 0);
    }
}

