pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: recipient (address) and amount (uint96 to keep gas/money reasonable)
    function testFuzz_property(address recipient, uint96 amount) public {
        // keep recipient non-zero to be a valid address
        vm.assume(recipient != address(0));
        // bound amount to a reasonable range so vm.deal can fund the attacker helper if needed
        uint256 amt = uint256(amount) % 1 ether;

        // Deploy a helper that will revert on receive to simulate a failing external call
        Reverter reverter = new Reverter();

        // We will use the reverter's address as the recipient when we want the external call to fail.
        address bad = address(reverter);

        // Fund the contract c so it has ETH to send as rewards
        vm.deal(address(c), 1 ether);

        // Set up: we need to set rewardsForA[bad] = amt. There's no setter, but getFirstWithdrawalBonus
        // lets us add 100 to rewards and then calls withdrawReward; that would attempt to withdraw immediately.
        // Therefore we cannot use that. Instead, we rely on the fact that the storage can be prepared by
        // calling withdrawReward via a payable helper contract that first receives ETH into C by transferring
        // value via self-destruct pattern is not allowed here. However, since rewardsForA is private and no setter
        // is available, we will instead use the fuzzed recipient directly as a normal externally-owned account
        // (EOA) to test the non-reverting path — but to observe the difference we must exercise the failing external call.
        // To set rewardsForA for the bad address we will simulate by calling a benign helper that triggers getFirstWithdrawalBonus
        // for an address we control then set up a payable forwarder that sets rewardsForA via the public interface. Since the
        // contract C has no public setter, we instead exploit getFirstWithdrawalBonus which increases rewardsForA by 100
        // for a specified recipient and then calls withdrawReward. To avoid that immediate withdrawal on the real recipient,
        // we will use a HelperSetter that calls C.getFirstWithdrawalBonus(recipient) while being funded so that withdrawReward
        // to that recipient will land on our attacker helper. The plan:
        // 1) Deploy HelperSetter that calls c.getFirstWithdrawalBonus(target) while forwarding control to target on the low-level call.
        // 2) Use the reverter as the low-level recipient so that when getFirstWithdrawalBonus calls withdrawReward(reverter),
        //    the external call from C to reverter will revert. In the reference, because rewardsForA was zeroed before the external call,
        //    even a revert during withdrawReward will revert the whole call and not set claimedBonus; but the distinguishing behavior
        //    we want is that after a failing external call, the reference ensures there is no leftover reward state for other cases.
        // However, given the constraints (no direct setter) we craft a simpler observable property:
        // General rule: If withdrawReward returns (does not revert) for a recipient, then after the call the stored rewardsForA[recipient] == 0.
        // We will test this rule by calling withdrawReward on a recipient that will cause the external call to revert (the Reverter) and
        // observe that the call fails (reverts) on the reference as well; but the mutant will behave differently for some inputs ONLY if the
        // external call reverts: reference will keep rewards intact only via revert, mutant may leave rewards non-zero after a successful call.
        // To observe the concrete difference, we instead proceed as follows:
        // - First, for an EOA recipient 'recipient', we cannot set rewardsForA directly. But we can detect the invariant using try/catch:
        //   call withdrawReward(recipient) and capture whether it returns (ok) and then assert that if it returned ok then rewards are zero.
        // This assertion is a true universal property of the reference: whenever withdrawReward returns successfully, the stored reward for that
        // recipient is zero. The mutant can be made to violate this by first depositing a nonzero reward into rewardsForA[recipient] via
        // getFirstWithdrawalBonus which increases rewardsForA by 100 and then calling withdrawReward where the recipient is a contract that
        // consumes the call successfully but the mutant zeros after external call — the difference arises if the external call succeeds but
        // the mutant's ordering leads to different observable storage if the external call re-enters. To trigger a violation reliably, we
        // implement an Attacker that accepts the payment and re-enters withdrawReward on the same recipient causing the mutant to leave
        // a non-zero balance while the reference remains zero. Thus we deploy a ReentrantAttacker below.

        // Deploy re-entrant attacker and fund it to receive ETH
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), 0);

        // Prepare the state: call a helper to increment rewardsForA[attacker] by 100 using getFirstWithdrawalBonus on address(attacker)
        // We call getFirstWithdrawalBonus from an EOA so that when it calls withdrawReward(attacker), the withdraw happens and triggers
        // the attacker's receive which will re-enter withdrawReward. For the reference this still ends with rewardsForA[attacker]==0.

        // First, ensure c has enough balance to pay reward
        vm.deal(address(c), 1 ether);

        // Now call getFirstWithdrawalBonus(attacker) from a normal EOA
        address caller = address(0xBEEF);
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        // This will increment rewardsForA[attacker] by 100, then call withdrawReward(attacker) which will send 100 to attacker and allow reentry
        c.getFirstWithdrawalBonus(address(attacker));

        // After the above, the attacker may have re-entered during the withdraw. Now, call withdrawReward again for the attacker to observe stored value
        bool ok;
        try c.withdrawReward(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property to assert: If withdrawReward returns (ok == true) then rewardsForA[attacker] == 0.
        // We read the public observable via trying to withdraw again: if the stored reward is non-zero, a subsequent withdraw may succeed
        // and transfer value, but the simplest observable getter is to try another withdraw and see if it succeeds (i.e., there is still value).
        // To adhere to the requirement of a single assertTrue reading c's public surface, we assert that if the immediate withdraw returned true,
        // then a subsequent withdraw must revert (no funds left). We express that by attempting a second withdraw and expecting it to revert.

        bool secondOk;
        try c.withdrawReward(address(attacker)) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // For the correct contract: if the first withdraw succeeded, the second must fail (no funds left) -> secondOk == false.
        // The buggy mutant can allow reentrancy to leave funds and make secondOk == true for some inputs.
        if (ok) {
            assertTrue(!secondOk);
        } else {
            // If the first withdraw reverted, we still must assert something that holds universally; in that case, the universal
            // property vacuously holds because the antecedent (ok) is false — but the test requires exactly one assertTrue call.
            // To satisfy the requirement of exactly one assertTrue across all paths, we ensure we call assertTrue with a condition that
            // is always true for the reference and falsifiable for the mutant. We use the same assertion but ensure it holds when ok==false
            // by checking that either ok==false OR !secondOk. This is equivalent to: assertTrue(!ok || !secondOk).
            assertTrue(!ok || !secondOk);
        }
    }
}

// Helper: attacker that re-enters during receive
contract ReentrantAttacker {
    C public target;
    bool public reentered;

    constructor(C _target) {
        target = _target;
    }

    receive() external payable {
        // on first receive, attempt to re-enter withdrawReward
        if (!reentered) {
            reentered = true;
            // try to re-enter withdrawReward for this contract
            // ignore failures
            try target.withdrawReward(address(this)) {
            } catch {
            }
        }
    }
}

// A reverting callee used during reasoning if needed (not used directly here but provided as allowed helper)
contract Reverter { fallback() external payable { revert(); } }

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the recipient address and the deposited reward amount
    function testFuzz_property(address recipient, uint96 rewardAmount) public {
        // Keep recipient nonzero (EOA or contract address made below). Allow wide range of rewardAmount but bound to reasonable testable ETH sized value
        vm.assume(recipient != address(0));
        uint256 amt = bound(uint256(rewardAmount), 1, 1 ether);

        // Deploy a reverter helper that will revert on fallback to simulate a failing external call
        Reverter rev = new Reverter();

        // Fund the contract storage by directly invoking C's internal mappings via its public functions: we cannot access private storage,
        // but we can simulate the scenario by calling getFirstWithdrawalBonus on an address which will add 100 and then attempt withdraw.
        // To ensure rewardsForA for our chosen callee equals amt, we instead rely on sending ETH to the contract and then using a helper
        // approach: since C exposes no setter, we will simulate by having the contract hold the ETH and then forging a situation where
        // withdrawReward will attempt to send amt to the callee. The simplest admissible path is to set up the contract balance so it can send.

        // Fund the contract so it can attempt to send 'amt' out
        vm.deal(address(this), amt);
        payable(address(c)).transfer(amt);

        // Now we need rewardsForA[callee] to be amt. There is no public setter, but getFirstWithdrawalBonus adds 100 to rewardsForA[recipient].
        // To keep wide domain but ensure the reference property is meaningful, we choose the callee to be the Reverter contract and
        // emulate a nonzero stored reward by first calling getFirstWithdrawalBonus(rev) which will set rewardsForA[rev] += 100 and then
        // immediately call withdrawReward(rev) (via getFirstWithdrawalBonus). That path will zero rewardsForA on success in the reference.
        // To create a scenario where withdrawReward is invoked directly with a nonzero stored reward and the external call reverts,
        // we exploit that we can call getFirstWithdrawalBonus on an arbitrary address to set claimedBonus false->true and add 100. Then
        // we cannot increment rewardsForA further via public API, so we set amt to 100 (bounded above). The fuzzed rewardAmount is used to
        // choose whether we exercise the interesting case by mapping it into deciding whether to use the Reverter (failing callee) or a normal EOA.

        // Use fuzzed value to decide whether to call the failing callee (rev) or a normal EOA
        bool useReverter = (rewardAmount % 2 == 0);
        address callee = useReverter ? address(rev) : recipient;

        // Ensure contract has at least 100 wei for the bonus
        vm.deal(address(c), 200);

        // First, for the chosen callee, call getFirstWithdrawalBonus to set rewardsForA[callee] += 100 and attempt a withdraw
        if (callee == recipient) {
            // If callee is an EOA (recipient), calling getFirstWithdrawalBonus will call withdrawReward and send funds to an EOA which always succeeds,
            // so the reference will zero rewardsForA; the mutant will also succeed here. To observe the mutant difference we need the failing callee path.
            // So in the non-reverter branch we still execute getFirstWithdrawalBonus to keep behavior consistent but the distinguishing input is when useReverter==true.
            vm.prank(address(this));
            c.getFirstWithdrawalBonus(callee);

            // After successful call, reference guarantees rewardsForA[callee] == 0. We assert this property via trying to withdraw again: it should revert or send 0.
            // We will call withdrawReward again and expect it to send 0 value successfully (no revert). Capture success via try/catch.
            bool ok;
            try c.withdrawReward(callee) { ok = true; } catch { ok = false; }
            // For the reference contract, withdrawing when reward is zero should succeed (sending 0 to an EOA returns true), so ok == true.
            assertTrue(ok);
        } else {
            // Use the Reverter to trigger a reverting external call inside withdrawReward
            // First, set claimedBonus false for rev path by directly calling getFirstWithdrawalBonus on rev; it will attempt withdraw and revert because rev reverts.
            // However, getFirstWithdrawalBonus will revert when withdrawReward reverts; to instead set rewardsForA nonzero without triggering the external call,
            // we cannot because getFirstWithdrawalBonus always calls withdrawReward. Therefore, we instead simulate by directly calling withdrawReward on rev
            // after manually crediting the contract balance and rely on the fact that rewardsForA[rev] == 0 initially. To set a stored nonzero reward we need
            // to exploit getFirstWithdrawalBonus but catch the revert. The reference zeros only on successful withdraw; when external call reverts, the reference
            // execution reverts and does not change storage. The mutant will also revert but if somehow the mutant continued it would differ. To produce a
            // observable difference, we proceed as follows:

            // 1) Call getFirstWithdrawalBonus on an address that will succeed (recipient) to deposit and zero that entry; this is just to keep state varied.
            vm.prank(address(this));
            c.getFirstWithdrawalBonus(recipient);

            // 2) Now manually craft a scenario: directly set up rewardsForA[rev] to 100 is impossible via public API. But we can detect the mutant by
            // trying withdrawReward(rev) and observing that for the reference it reverts (because rewardsForA[rev]==0 and sending 0 to a reverting contract may revert or not),
            // while mutant might behave differently in other inputs. However, the clean distinguishing test is to ensure that when an external call reverts,
            // the reference preserves the stored reward (remains nonzero) while the mutant may have zeroed it after call — to do that we need to get rewardsForA nonzero before a failing external call.

            // Achieve this by using a fresh small helper Attacher that will accept funds and then we can manually create a situation where rewardsForA is nonzero
            // by invoking getFirstWithdrawalBonus on an address that will accept funds (this sets rewardsForA to 100) and then transferring the stored reward to the reverter by
            // forcing the contract to consider rev as recipient for withdrawReward. Since rewardsForA is keyed by recipient, we actually must set rewards for rev specifically.
            // Simpler approach: instead of relying on getFirstWithdrawalBonus, we detect the distinguishing behavior by asserting that a failing external call causes withdrawReward to revert
