        // fund the helper so it can receive/forward value if needed
        vm.deal(address(hs), 1 ether);

        // Use the helper to bump rewardsForA[rev] by priorReward via repeated calls to an internal path.
        // Since C only increases by exactly 100 in getFirstWithdrawalBonus (in the reference it adds 100),
        // we loop to add blocks of 100 until we reach priorReward (coarse approximation). Keep loop small to avoid gas issues.
        uint256 chunks = priorReward / 100;
        if (chunks > 100) chunks = 100; // keep bounded
        for (uint256 i = 0; i < chunks; i++) {
            hs.callGetFirstWithdrawalBonus(address(rev));
        }
        // leftover remainder (not perfectly precise, but we only need variation in prior state)

        // Record rewardsForA before invoking the tested call by observing address(c).balance difference possibility
        // There's no getter for rewardsForA (private), so we must rely on observable difference: after a failing withdraw,
        // reference preserves previous (nonzero) internal stored rewards that lead to unchanged behavior on subsequent calls.
        // We'll check that calling getFirstWithdrawalBonus again on the same recipient (which still hasn't claimed) will revert
        // in the mutant scenario or behave differently. To create an observable property that reference preserves for all inputs
        // but mutant violates for some, we use this operational test:

        // First, ensure claimedBonus[rev] is false; our helper calls above will have attempted withdrawals which revert,
        // but getFirstWithdrawalBonus sets claimedBonus after withdrawReward; since withdraw reverted, claimedBonus remains false.

        // Now call the target function via a transaction coming from any account; ensure the withdraw will fail by passing rev address.
        bool ok;
        try c.getFirstWithdrawalBonus(address(rev)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: when the external call fails (Reverter always reverts), the reference contract
        // leaves claimedBonus[rev] == false (because withdrawReward reverted and modifier/_flow prevents marking claimed),
        // but the mutant that overwrote rewardsForA could still leave claimedBonus == false; however the distinguishing
        // observable we can assert across both versions is that address(c).balance remains unchanged for the reference for ALL inputs
        // because withdrawReward attempted to send funds but failed, so the contract should not have transferred Ether out.
        // The mutant may have different stored rewards but still cannot change Ether balance on failed call — thus this is insufficient.

        // Instead, we assert a property that the reference ALWAYS ensures that after calling getFirstWithdrawalBonus on a reverter,
        // the call DOES NOT set claimedBonus to true (since withdraw failed). We can observe claimedBonus via calling again: the second
        // call should still be allowed (i.e., not revert due to already claimed). So we perform a second call and expect it to execute (ok2==true).
        bool ok2;
        try c.getFirstWithdrawalBonus(address(rev)) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Single assertion: in the correct contract, both attempts should be allowed (withdraw fails and claimedBonus stays false),
        // so ok && ok2 must be true for all admissible inputs; the mutant can in some situations overwrite rewards and cause a different
        // control flow making one of these calls revert or behave differently (the fuzzer will find such inputs).
        assertTrue(ok && ok2);
    }
}

// Helper that attempts to call getFirstWithdrawalBonus on C (used to set some prior state)
contract HelperSetter {
    C c;
    constructor(C _c) { c = _c; }
    function callGetFirstWithdrawalBonus(address recipient) external {
        // call without sending Ether; target contract will attempt to send, which may revert in Reverter
        try c.getFirstWithdrawalBonus(recipient) {
        } catch {}
    }
}

// adversarial callee that always reverts on fallback/receive
contract Reverter {
    fallback() external payable { revert("revert"); }
    receive() external payable { revert("revert"); }
}

