contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive the contract: deposit Ether to this test, then call getFirstWithdrawalBonus(recipient)
    // and assert that the contract's balance decreased by at least 100 (the rewarded amount).
    // We take recipient as parameter so verifier can try different addresses.
    function runTest(address payable recipient, uint deposit) public payable {
        require(msg.value == deposit);
        // send funds to c so it can pay out
        (bool s,) = address(c).call{value: deposit}("");
        require(s);

        uint before = address(c).balance;

        // call the function under test
        c.getFirstWithdrawalBonus(recipient);

        uint after = address(c).balance;

        // On the original contract, the recipient should have been paid the bonus (100),
        // so the contract balance must have decreased by at least 100.
        // In the mutant that sets claimedBonus before the require, the require blocks the bonus
        // check and withdrawal may not happen, so balance may not drop by 100.
        assert(before - after >= 100);
    }

    // allow receiving refunds if needed
    receive() external payable {}
}

